struct Step { std::function<Step()> more; std::optional<long> value; };

Step even(long n);
Step odd(long n);

Step even(long n) { return n == 0 ? Step{{}, 1L} : Step{[n]{ return odd(n - 1); }, {}}; }
Step odd(long n)  { return n == 0 ? Step{{}, 0L} : Step{[n]{ return even(n - 1); }, {}}; }

long run(Step s) { while (s.more) s = s.more(); return *s.value; }

